create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text,
  full_name text,
  role text not null default 'student' check (role in ('student','mentor','admin')),
  program text default 'ASTRUM',
  mentor_id uuid references public.profiles(id),
  created_at timestamptz not null default now()
);

create table if not exists public.sources (
  id text primary key,
  title text not null,
  official_source text,
  tier text,
  domain text,
  theme text,
  pathways text,
  core_selective text,
  public_url text,
  phase2 boolean default false,
  content jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.source_progress (
  user_id uuid not null references public.profiles(id) on delete cascade,
  source_id text not null references public.sources(id) on delete cascade,
  status text not null default 'not_started' check (status in ('not_started','in_progress','completed')),
  percent integer not null default 0 check (percent between 0 and 100),
  completed_at timestamptz,
  notes text,
  updated_at timestamptz not null default now(),
  primary key (user_id, source_id)
);

create table if not exists public.weekly_plans (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  mentor_id uuid references public.profiles(id),
  week_of date not null,
  source_ids text[] default '{}',
  learning_goal text,
  activities text,
  expected_hours numeric(6,2) default 0,
  dash_deliverable text,
  status text default 'planned' check (status in ('planned','active','completed','reviewed')),
  mentor_feedback text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.diary_entries (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  entry_date date not null default current_date,
  source_id text references public.sources(id),
  activity text not null,
  hours numeric(6,2) not null default 0 check (hours >= 0),
  reflection text,
  evidence_url text,
  mentor_review text,
  created_at timestamptz not null default now()
);

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name',''))
  on conflict (id) do nothing;
  return new;
end; $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
for each row execute procedure public.handle_new_user();

-- Security-definer helpers prevent recursive RLS checks on profiles.
create or replace function public.current_user_role()
returns text language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid();
$$;

create or replace function public.is_mentor_for(student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists(
    select 1 from public.profiles
    where id = student and mentor_id = auth.uid()
  );
$$;

alter table public.profiles enable row level security;
alter table public.sources enable row level security;
alter table public.source_progress enable row level security;
alter table public.weekly_plans enable row level security;
alter table public.diary_entries enable row level security;

-- Drop policies so the setup script is safely re-runnable.
drop policy if exists "authenticated read sources" on public.sources;
drop policy if exists "admin manage sources" on public.sources;
drop policy if exists "profile self mentor admin read" on public.profiles;
drop policy if exists "progress self mentor admin read" on public.source_progress;
drop policy if exists "progress self write" on public.source_progress;
drop policy if exists "plans authorized read" on public.weekly_plans;
drop policy if exists "plans authorized insert" on public.weekly_plans;
drop policy if exists "plans authorized update" on public.weekly_plans;
drop policy if exists "diary authorized read" on public.diary_entries;
drop policy if exists "diary student insert" on public.diary_entries;
drop policy if exists "diary authorized update" on public.diary_entries;

create policy "authenticated read sources" on public.sources
for select to authenticated using (true);

create policy "admin manage sources" on public.sources
for all to authenticated
using (public.current_user_role() = 'admin')
with check (public.current_user_role() = 'admin');

create policy "profile self mentor admin read" on public.profiles
for select to authenticated using (
  id = auth.uid() or mentor_id = auth.uid() or public.current_user_role() = 'admin'
);

create policy "progress self mentor admin read" on public.source_progress
for select to authenticated using (
  user_id = auth.uid() or public.is_mentor_for(user_id) or public.current_user_role() = 'admin'
);

create policy "progress self write" on public.source_progress
for all to authenticated
using (user_id = auth.uid())
with check (user_id = auth.uid());

create policy "plans authorized read" on public.weekly_plans
for select to authenticated using (
  student_id = auth.uid() or mentor_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
);

create policy "plans authorized insert" on public.weekly_plans
for insert to authenticated with check (
  student_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
);

create policy "plans authorized update" on public.weekly_plans
for update to authenticated using (
  student_id = auth.uid() or mentor_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
) with check (
  student_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
);

create policy "diary authorized read" on public.diary_entries
for select to authenticated using (
  student_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
);

create policy "diary student insert" on public.diary_entries
for insert to authenticated with check (student_id = auth.uid());

create policy "diary authorized update" on public.diary_entries
for update to authenticated using (
  student_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
) with check (
  student_id = auth.uid() or public.is_mentor_for(student_id) or public.current_user_role() = 'admin'
);
begin;
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M01','Space Force Doctrine Document 1 - The Space Force','USSF','Tier 1 - Core Astrum Source','Spacepower / doctrine','Doctrine, warfighting, and institutional identity','ASTRUM Foundations; Spacepower & Guardian Doctrine','Core','https://www.spaceforce.mil/USSF-Doctrine/',true,'{"brief":{"Source ID":"M01","Brief ID":"AB-M01","Proposed Brief Title":"Why the Space Force Exists and What It Demands of an Astrum Scholar","Brief Abstract / Teaching Angle":"This Astrum Brief converts the source into an operational reading of how the U.S. Space Force thinks about purpose, competitive advantage, campaigning, and warfighting. Students use it not just to memorize doctrine, but to identify how institutional ideas shape force design, mission command, risk tolerance, and the meaning of space superiority. The brief should finish with a short section on what the document implies for cyber trust, data assurance, and multidisciplinary Guardian education.","Key Learning Payoff":"Why the Service exists; foundational doctrine.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M01","Lens ID":"RL-M01","Raven''s Lens Commentary":"Astrum reads this source as a statement of worldview. The document tells us what the Service believes about advantage, competition, and mission success. The proprietary layer is asking what this worldview assumes about trustworthy information, survivable records, cyber resilience, and the ability of a commander to distinguish confidence from mere data volume.","Hidden Assumption":"That commanders will have timely, coherent, and sufficiently trusted information when doctrine must be applied.","Likely Failure Point":"Conceptual clarity without enough operational guidance on trusted-data decision chains.","What They Didn''t Say":"How authoritative truth is preserved when the mission depends on mixed military, allied, and commercial data.","Signature Raven Question":"What part of this strategy fails first if the information environment becomes unreliable?"},"questions":{"Source ID":"M01","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What conception of advantage, restraint, and escalation does this source assume?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"If you had to teach this to a new Astrum student in ten minutes, what would you emphasize?"},"audio":{"Source ID":"M01","Audio ID":"AA-M01","Episode / Briefing Title":"Why the Space Force Exists and What It Demands of an Astrum Scholar","Est. Duration":"8-10 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Spacepower sounds abstract until a commander must act without certainty. This source tells us what the Service expects to matter when that moment comes.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What part of this strategy fails first if the information environment becomes unreliable?"},"visual":{"Source ID":"M01","Visual ID":"AV-M01","Asset Title":"Doctrine-to-Mission Map","Recommended Format":"1-page doctrine map","Key Story the Visual Should Tell":"Purpose → mission functions → decision burdens → trust dependencies","Must-Show Elements":"Use icon layers for doctrine, missions, cyber, intelligence, and command.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M01","Linked Inject IDs":"INJ-10, INJ-12","Suggested Assignment IDs":"A01, A03","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M01","Research Vector":"Research how doctrine and strategic guidance account for trusted data, cyber resilience, and commercial integration in actual decision chains.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"ASTRUM Foundations; Spacepower & Guardian Doctrine"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
