insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M05','USSF Doctrine Digital Library','USSF','Tier 1 - Core Astrum Source','Doctrine library','Doctrine, warfighting, and institutional identity','ASTRUM Foundations; Spacepower & Guardian Doctrine','Core','https://www.spaceforce.mil/USSF-Doctrine/',false,'{"brief":{"Source ID":"M05","Brief ID":"AB-M05","Proposed Brief Title":"USSF Doctrine Digital Library","Brief Abstract / Teaching Angle":"This Astrum Brief converts the source into an operational reading of how the U.S. Space Force thinks about purpose, competitive advantage, campaigning, and warfighting. Students use it not just to memorize doctrine, but to identify how institutional ideas shape force design, mission command, risk tolerance, and the meaning of space superiority. The brief should finish with a short section on what the document implies for cyber trust, data assurance, and multidisciplinary Guardian education.","Key Learning Payoff":"SDA, intelligence, operations, planning, mission command, sustainment.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M05","Lens ID":"RL-M05","Raven''s Lens Commentary":"Astrum reads this source as a statement of worldview. The document tells us what the Service believes about advantage, competition, and mission success. The proprietary layer is asking what this worldview assumes about trustworthy information, survivable records, cyber resilience, and the ability of a commander to distinguish confidence from mere data volume.","Hidden Assumption":"That commanders will have timely, coherent, and sufficiently trusted information when doctrine must be applied.","Likely Failure Point":"Conceptual clarity without enough operational guidance on trusted-data decision chains.","What They Didn''t Say":"How authoritative truth is preserved when the mission depends on mixed military, allied, and commercial data.","Signature Raven Question":"What part of this strategy fails first if the information environment becomes unreliable?"},"questions":{"Source ID":"M05","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What conception of advantage, restraint, and escalation does this source assume?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"If you had to teach this to a new Astrum student in ten minutes, what would you emphasize?"},"audio":{"Source ID":"M05","Audio ID":"AA-M05","Episode / Briefing Title":"USSF Doctrine Digital Library","Est. Duration":"8-10 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Spacepower sounds abstract until a commander must act without certainty. This source tells us what the Service expects to matter when that moment comes.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What part of this strategy fails first if the information environment becomes unreliable?"},"visual":{"Source ID":"M05","Visual ID":"AV-M05","Asset Title":"Doctrine-to-Mission Map","Recommended Format":"1-page doctrine map","Key Story the Visual Should Tell":"Purpose → mission functions → decision burdens → trust dependencies","Must-Show Elements":"Use icon layers for doctrine, missions, cyber, intelligence, and command.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M05","Linked Inject IDs":"INJ-10","Suggested Assignment IDs":"A01, A03","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M05","Research Vector":"Research how doctrine and strategic guidance account for trusted data, cyber resilience, and commercial integration in actual decision chains.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"ASTRUM Foundations; Spacepower & Guardian Doctrine"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M06','U.S. Space Force Commercial Space Strategy','USSF','Tier 1 - Core Astrum Source','Commercial integration','Commercial integration and service dependency','Commercial Integration','Core','https://www.spaceforce.mil/Portals/2/Documents/Space%20Policy/USSF_Commercial_Space_Strategy.pdf',true,'{"brief":{"Source ID":"M06","Brief ID":"AB-M06","Proposed Brief Title":"Commercial Space as an Operational Dependency","Brief Abstract / Teaching Angle":"This Astrum Brief contextualizes the source for mission-critical space education. It identifies why the material matters now, what it teaches about mission systems, and how it can be translated into an exercise, scenario, or research question rather than remaining a passive reading.","Key Learning Payoff":"Hybrid organic/allied/commercial architectures.","What Changed / Why Now":"Commercial capability is moving from vendor support to operational dependency, which raises assurance and sovereignty questions.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M06","Lens ID":"RL-M06","Raven''s Lens Commentary":"The Raven''s Lens uses the source to surface the trust assumptions hiding underneath the official language.","Hidden Assumption":"That commercial capability can be integrated without unacceptable assurance, sovereignty, or continuity tradeoffs.","Likely Failure Point":"Dependency on vendors whose assurance model does not fully align with mission needs.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"What conditions must be true before a commercial service becomes mission-trustworthy?"},"questions":{"Source ID":"M06","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Which commercial dependency in this source would you scrutinize first?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"How could foreign ownership, legal jurisdiction, or vendor lock-in change the risk?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M06","Audio ID":"AA-M06","Episode / Briefing Title":"Commercial Space as an Operational Dependency","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"The future mission stack is increasingly commercial. The issue is no longer whether to integrate vendors, but how to trust them.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What conditions must be true before a commercial service becomes mission-trustworthy?"},"visual":{"Source ID":"M06","Visual ID":"AV-M06","Asset Title":"Astrum Source Explainer","Recommended Format":"1-page visual brief","Key Story the Visual Should Tell":"Source purpose, system map, trust point, and one decision problem","Must-Show Elements":"A flexible format for any source.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M06","Linked Inject IDs":"INJ-04, INJ-11","Suggested Assignment IDs":"A28, A29, A31","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Decide whether and under what conditions a commercial provider should be integrated into a mission-critical architecture.","Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M06","Research Vector":"Research how doctrine and strategic guidance account for trusted data, cyber resilience, and commercial integration in actual decision chains.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Commercial Integration"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
