insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M08','STARCOM Partnership Days - Guardian Education','STARCOM','Tier 2 - Selective / elective source','Education','Education, training, and workforce development','Workforce & Education','Selective','https://www.spaceforce.mil/News/Article-Display/Article/4150335/ussf-releases-new-capstone-doctrine/',false,'{"brief":{"Source ID":"M08","Brief ID":"AB-M08","Proposed Brief Title":"STARCOM Partnership Days - Guardian Education","Brief Abstract / Teaching Angle":"This brief is used to interpret the source as a workforce-development signal. It draws out the explicit and implied educational needs behind the document, including multidisciplinary preparation, cyber-cognitive readiness, research needs, and how Astrum can prototype academic responses faster than formal institutions typically can.","Key Learning Payoff":"Signals desired academic/industry partnership areas.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"Short written analysis with one visual and a reflective diary entry."},"lens":{"Source ID":"M08","Lens ID":"RL-M08","Raven''s Lens Commentary":"Astrum uses this source to identify the gap between the space workforce institutions the nation has and the ones the emerging mission environment actually requires.","Hidden Assumption":"That the architecture will behave as designed even when the mission is stressed, degraded, or contested.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"questions":{"Source ID":"M08","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M08","Audio ID":"AA-M08","Episode / Briefing Title":"STARCOM Partnership Days - Guardian Education","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Education policy matters because institutions shape the people who will carry tomorrow''s missions.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"visual":{"Source ID":"M08","Visual ID":"AV-M08","Asset Title":"Astrum Workforce Map","Recommended Format":"Curriculum architecture visual","Key Story the Visual Should Tell":"Doctrine, cyber, AI, acquisition, research, and mission exercises","Must-Show Elements":"Use to explain why Astrum exists.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M08","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A39, A40, A41","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Short written analysis with one visual and a reflective diary entry.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M08","Research Vector":"Design and test a multidisciplinary curriculum model for spacepower education aligned to emerging Guardian and civilian workforce needs.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Workforce & Education"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M09','STARCOM Cyber Readiness','STARCOM','Tier 2 - Selective / elective source','Cyber workforce','Education, training, and workforce development','Space Cybersecurity; Mission Assurance; Workforce & Education','Selective','https://www.spaceforce.mil/News/Article-Display/Article/4156245/ussf-defines-path-to-space-superiority-in-first-warfighting-framework/',false,'{"brief":{"Source ID":"M09","Brief ID":"AB-M09","Proposed Brief Title":"STARCOM Cyber Readiness","Brief Abstract / Teaching Angle":"This brief is used to interpret the source as a workforce-development signal. It draws out the explicit and implied educational needs behind the document, including multidisciplinary preparation, cyber-cognitive readiness, research needs, and how Astrum can prototype academic responses faster than formal institutions typically can.","Key Learning Payoff":"Cyber training and readiness priorities.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk."},"lens":{"Source ID":"M09","Lens ID":"RL-M09","Raven''s Lens Commentary":"Astrum uses this source to identify the gap between the space workforce institutions the nation has and the ones the emerging mission environment actually requires.","Hidden Assumption":"That security controls alone guarantee mission confidence without a clear evidentiary model.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"Which controls matter most when mission continuity and operational decision quality—not just compliance—are the central goals.","Signature Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"questions":{"Source ID":"M09","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Where are the highest-value trust boundaries: identity, software, ground segment, or data path?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Which failure would hurt the mission most even if the organization remained technically compliant?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M09","Audio ID":"AA-M09","Episode / Briefing Title":"STARCOM Cyber Readiness","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Cybersecurity becomes mission-critical when a single weak link can quietly distort the operational picture.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"visual":{"Source ID":"M09","Visual ID":"AV-M09","Asset Title":"Astrum Workforce Map","Recommended Format":"Curriculum architecture visual","Key Story the Visual Should Tell":"Doctrine, cyber, AI, acquisition, research, and mission exercises","Must-Show Elements":"Use to explain why Astrum exists.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M09","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M09","Research Vector":"Identify a measurable trust, resilience, or mission-assurance gap implied by the source and frame it as a publishable research question.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Space Cybersecurity; Mission Assurance; Workforce & Education"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
