insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M14','Space Development Agency - PWSA Overview','SDA','Tier 1 - Core Astrum Source','Architecture','Mission assurance and space systems','Resilient Architectures; Mission Systems','Core','https://www.sda.mil/home/about-us/',true,'{"brief":{"Source ID":"M14","Brief ID":"AB-M14","Proposed Brief Title":"Understanding the Proliferated Warfighter Space Architecture","Brief Abstract / Teaching Angle":"This brief explains the source as part of a larger mission system. Students should come away able to explain what role the architecture plays, what data flows through it, what dependencies it creates, and which trust boundaries or failure points deserve special scrutiny when the constellation is under stress or partially degraded.","Key Learning Payoff":"Proliferated Warfighter Space Architecture.","What Changed / Why Now":"Force design is shifting toward proliferation, resilience, and reconstitution, which multiplies trust boundaries and cyber complexity.","Suggested Dash Deliverable":"Mission architecture visual + short decision brief."},"lens":{"Source ID":"M14","Lens ID":"RL-M14","Raven''s Lens Commentary":"The hidden lesson is that proliferated architecture creates strategic resilience and operational complexity at the same time. Astrum uses this source to train students to see every additional link, node, interface, and autonomy feature as both a capability gain and a new assurance obligation.","Hidden Assumption":"That the architecture will behave as designed even when the mission is stressed, degraded, or contested.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"questions":{"Source ID":"M14","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M14","Audio ID":"AA-M14","Episode / Briefing Title":"Understanding the Proliferated Warfighter Space Architecture","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Astrum uses this source to turn static reading into a mission briefing about trust, resilience, and decision quality.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"visual":{"Source ID":"M14","Visual ID":"AV-M14","Asset Title":"Astrum Source Explainer","Recommended Format":"1-page visual brief","Key Story the Visual Should Tell":"Source purpose, system map, trust point, and one decision problem","Must-Show Elements":"A flexible format for any source.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M14","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A04, A15, A17","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Mission architecture visual + short decision brief.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M14","Research Vector":"Identify a measurable trust, resilience, or mission-assurance gap implied by the source and frame it as a publishable research question.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Resilient Architectures; Mission Systems"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M15','SDA Tracking Layer','SDA','Tier 1 - Core Astrum Source','Missile warning/tracking','Missile warning, tracking, and sensor confidence','Resilient Architectures; Mission Systems','Core','https://www.sda.mil/tracking/',true,'{"brief":{"Source ID":"M15","Brief ID":"AB-M15","Proposed Brief Title":"Trusted Missile Warning in a Proliferated Tracking Layer","Brief Abstract / Teaching Angle":"This brief focuses on the missile-warning and tracking problem as a trust problem as much as a sensing problem. It turns the source into a concise explanation of what the layer does, why latency and confidence matter, and how a commander should think about provenance, disagreement between sensors, and the burden of decision when warning data drives defensive action.","Key Learning Payoff":"Persistent sensing and missile defense architecture.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"Mission architecture visual + short decision brief."},"lens":{"Source ID":"M15","Lens ID":"RL-M15","Raven''s Lens Commentary":"The Raven''s Lens reframes missile warning as a confidence architecture problem. Detection is not enough; the crucial issue is whether the system can justify belief under time pressure when multiple sensors, networks, and decision layers are involved.","Hidden Assumption":"That data from a proliferated sensor architecture can be fused faster than uncertainty accumulates.","Likely Failure Point":"Conflicting observations or degraded confidence under time pressure.","What They Didn''t Say":"How provenance, confidence scoring, and post-mission audit should work across the full end-to-end chain.","Signature Raven Question":"When sensors disagree, what should count as authoritative truth?"},"questions":{"Source ID":"M15","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"How much confidence is enough before warning data drive a defensive or escalatory decision?","CQ-4":"How would you adjudicate disagreement between sensors or data providers?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M15","Audio ID":"AA-M15","Episode / Briefing Title":"Trusted Missile Warning in a Proliferated Tracking Layer","Est. Duration":"7-9 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Missile warning is not only a sensing challenge; it is a confidence challenge. Who do you trust when seconds matter?","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"When sensors disagree, what should count as authoritative truth?"},"visual":{"Source ID":"M15","Visual ID":"AV-M15","Asset Title":"Warning Confidence Ladder","Recommended Format":"Layered decision diagram","Key Story the Visual Should Tell":"Sensor → fusion → confidence → command decision → post-mission audit","Must-Show Elements":"Emphasize latency, provenance, and disagreement resolution.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M15","Linked Inject IDs":"INJ-06","Suggested Assignment IDs":"A04, A15, A17, A11","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Build a trusted missile-warning data chain and identify the single most consequential point of failure.","Dash Deliverable":"Mission architecture visual + short decision brief.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M15","Research Vector":"Study confidence scoring, provenance, or degraded-mode behavior in proliferated mission architectures.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Resilient Architectures; Mission Systems"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
