Question":"When sensors disagree, what should count as authoritative truth?"},"questions":{"Source ID":"M18","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M18","Audio ID":"AA-M18","Episode / Briefing Title":"Navigation Layer and the Future of GPS-Resilient Operations","Est. Duration":"7-9 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Imagine seventy-two hours without reliable PNT. This source matters because timing failure is civilizational failure as much as military friction.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"When sensors disagree, what should count as authoritative truth?"},"visual":{"Source ID":"M18","Visual ID":"AV-M18","Asset Title":"72 Hours Without PNT","Recommended Format":"Dependency cascade map","Key Story the Visual Should Tell":"GPS/PNT disruption effects across military and civilian sectors","Must-Show Elements":"Show mission, timing, finance, telecom, transportation, and power dependencies.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M18","Linked Inject IDs":"INJ-03","Suggested Assignment IDs":"A04, A15, A17, A24","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Design a continuity approach for a mission operating in a PNT-degraded environment.","Dash Deliverable":"Mission architecture visual + short decision brief.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M18","Research Vector":"Evaluate how resilient PNT architectures should expose uncertainty to downstream human and machine users.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Resilient Architectures; Mission Systems; PNT & Mission Data"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M19','SDA Tranche 3 Golden Dome Awards - July 2026','SDA','Tier 2 - Selective / elective source','Investment / missile defense','Investment signals, future force design, and strategic direction','Mission Systems','Selective','https://www.sda.mil/',false,'{"brief":{"Source ID":"M19","Brief ID":"AB-M19","Proposed Brief Title":"SDA Tranche 3 Golden Dome Awards - July 2026","Brief Abstract / Teaching Angle":"This brief focuses on the missile-warning and tracking problem as a trust problem as much as a sensing problem. It turns the source into a concise explanation of what the layer does, why latency and confidence matter, and how a commander should think about provenance, disagreement between sensors, and the burden of decision when warning data drives defensive action.","Key Learning Payoff":"Current funding signal: 36 additional tracking/defense satellites.","What Changed / Why Now":"Recent investment momentum reinforces that missile warning and defense tracking are not abstract topics; they are live force-building priorities.","Suggested Dash Deliverable":"Short written analysis with one visual and a reflective diary entry."},"lens":{"Source ID":"M19","Lens ID":"RL-M19","Raven''s Lens Commentary":"The Raven''s Lens reframes missile warning as a confidence architecture problem. Detection is not enough; the crucial issue is whether the system can justify belief under time pressure when multiple sensors, networks, and decision layers are involved.","Hidden Assumption":"That data from a proliferated sensor architecture can be fused faster than uncertainty accumulates.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"When sensors disagree, what should count as authoritative truth?"},"questions":{"Source ID":"M19","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M19","Audio ID":"AA-M19","Episode / Briefing Title":"SDA Tranche 3 Golden Dome Awards - July 2026","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Astrum uses this source to turn static reading into a mission briefing about trust, resilience, and decision quality.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"When sensors disagree, what should count as authoritative truth?"},"visual":{"Source ID":"M19","Visual ID":"AV-M19","Asset Title":"Astrum Source Explainer","Recommended Format":"1-page visual brief","Key Story the Visual Should Tell":"Source purpose, system map, trust point, and one decision problem","Must-Show Elements":"A flexible format for any source.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M19","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A39","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Build a trusted missile-warning data chain and identify the single most consequential point of failure.","Dash Deliverable":"Short written analysis with one visual and a reflective diary entry.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M19","Research Vector":"Identify a measurable trust, resilience, or mission-assurance gap implied by the source and frame it as a publishable research question.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Mission Systems"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M20','NIST IR 8270 - Introduction to Cybersecurity for Commercial Satellite Operations','NIST','Tier 1 - Core Astrum Source','Space cyber','Commercial integration and service dependency','Space Cybersecurity; Mission Assurance; Commercial Integration','Core','https://csrc.nist.gov/Pubs/ir/8270/final',true,'{"brief":{"Source ID":"M20","Brief ID":"AB-M20","Proposed Brief Title":"Commercial Satellite Cybersecurity as Mission Assurance","Brief Abstract / Teaching Angle":"This brief turns a technical cybersecurity source into an Astrum mission-assurance asset. Instead of presenting controls in isolation, the brief links them to spacecraft, ground segment, hybrid networks, software provenance, identity, and third-party dependencies. The learning objective is to make students see cyber guidance as a means of preserving mission continuity and decision confidence.","Key Learning Payoff":"Commercial satellite cyber risk management.","What Changed / Why Now":"These frameworks are increasingly used as translational bridges between technical security practice and mission assurance requirements.","Suggested Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk."},"lens":{"Source ID":"M20","Lens ID":"RL-M20","Raven''s Lens Commentary":"Astrum interprets this material through the language of trust boundaries. The key question is never just whether a control exists, but whether mission confidence survives when data cross organizational, software, orbital, terrestrial, and commercial boundaries.","Hidden Assumption":"That commercial capability can be integrated without unacceptable assurance, sovereignty, or continuity tradeoffs.","Likely Failure Point":"Interface ambiguity between spacecraft, ground, cloud, and partner systems.","What They Didn''t Say":"Which controls matter most when mission continuity and operational decision quality—not just compliance—are the central goals.","Signature Raven Question":"What conditions must be true before a commercial service becomes mission-trustworthy?"},"questions":{"Source ID":"M20","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Which commercial dependency in this source would you scrutinize first?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"How could foreign ownership, legal jurisdiction, or vendor lock-in change the risk?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M20","Audio ID":"AA-M20","Episode / Briefing Title":"Commercial Satellite Cybersecurity as Mission Assurance","Est. Duration":"7-9 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"The future mission stack is increasingly commercial. The issue is no longer whether to integrate vendors, but how to trust them.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What conditions must be true before a commercial service becomes mission-trustworthy?"},"visual":{"Source ID":"M20","Visual ID":"AV-M20","Asset Title":"Hybrid Satellite Trust Boundaries","Recommended Format":"Security architecture diagram","Key Story the Visual Should Tell":"Spacecraft, ground, cloud, users, APIs, partner systems","Must-Show Elements":"Label authentication, telemetry, command, update, and audit zones.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M20","Linked Inject IDs":"INJ-01, INJ-02, INJ-04, INJ-11","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M20","Research Vector":"Investigate how cybersecurity controls translate into measurable mission assurance outcomes in hybrid space systems.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Space Cybersecurity; Mission Assurance; Commercial Integration"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M21','NIST IR 8441 - Cybersecurity Framework Profile for Hybrid Satellite Networks','NIST','Tier 1 - Core Astrum Source','Hybrid cyber','Space mission cybersecurity and hybrid architecture assurance','Space Cybersecurity; Mission Assurance','Core','https://csrc.nist.gov/pubs/ir/8441/final',true,'{"brief":{"Source ID":"M21","Brief ID":"AB-M21","Proposed Brief Title":"Trust Boundaries in Hybrid Satellite Networks","Brief Abstract / Teaching Angle":"This brief turns a technical cybersecurity source into an Astrum mission-assurance asset. Instead of presenting controls in isolation, the brief links them to spacecraft, ground segment, hybrid networks, software provenance, identity, and third-party dependencies. The learning objective is to make students see cyber guidance as a means of preserving mission continuity and decision confidence.","Key Learning Payoff":"Interface and participant assurance in hybrid satellite networks.","What Changed / Why Now":"These frameworks are increasingly used as translational bridges between technical security practice and mission assurance requirements.","Suggested Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk."},"lens":{"Source ID":"M21","Lens ID":"RL-M21","Raven''s Lens Commentary":"Astrum interprets this material through the language of trust boundaries. The key question is never just whether a control exists, but whether mission confidence survives when data cross organizational, software, orbital, terrestrial, and commercial boundaries.","Hidden Assumption":"That security controls alone guarantee mission confidence without a clear evidentiary model.","Likely Failure Point":"Interface ambiguity between spacecraft, ground, cloud, and partner systems.","What They Didn''t Say":"Which controls matter most when mission continuity and operational decision quality—not just compliance—are the central goals.","Signature Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"questions":{"Source ID":"M21","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Where are the highest-value trust boundaries: identity, software, ground segment, or data path?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Which failure would hurt the mission most even if the organization remained technically compliant?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M21","Audio ID":"AA-M21","Episode / Briefing Title":"Trust Boundaries in Hybrid Satellite Networks","Est. Duration":"7-9 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Cybersecurity becomes mission-critical when a single weak link can quietly distort the operational picture.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"visual":{"Source ID":"M21","Visual ID":"AV-M21","Asset Title":"Hybrid Satellite Trust Boundaries","Recommended Format":"Security architecture diagram","Key Story the Visual Should Tell":"Spacecraft, ground, cloud, users, APIs, partner systems","Must-Show Elements":"Label authentication, telemetry, command, update, and audit zones.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M21","Linked Inject IDs":"INJ-01, INJ-02","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity"