insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M29','NIST SP 800-161r1 Cybersecurity Supply Chain Risk Management','NIST','Tier 2 - Selective / elective source','Supply chain','AI assurance, autonomy, and human judgment','Space Cybersecurity; Mission Assurance','Selective','https://www.defense.gov/News/Releases/Release/Article/3588743/cdao-releases-responsible-ai-rai-toolkit-for-ensuring-alignment-with-rai-best-p/',false,'{"brief":{"Source ID":"M29","Brief ID":"AB-M29","Proposed Brief Title":"NIST SP 800-161r1 Cybersecurity Supply Chain Risk Management","Brief Abstract / Teaching Angle":"This brief turns a technical cybersecurity source into an Astrum mission-assurance asset. Instead of presenting controls in isolation, the brief links them to spacecraft, ground segment, hybrid networks, software provenance, identity, and third-party dependencies. The learning objective is to make students see cyber guidance as a means of preserving mission continuity and decision confidence.","Key Learning Payoff":"C-SCRM practices for systems and organizations.","What Changed / Why Now":"These frameworks are increasingly used as translational bridges between technical security practice and mission assurance requirements.","Suggested Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk."},"lens":{"Source ID":"M29","Lens ID":"RL-M29","Raven''s Lens Commentary":"Astrum interprets this material through the language of trust boundaries. The key question is never just whether a control exists, but whether mission confidence survives when data cross organizational, software, orbital, terrestrial, and commercial boundaries.","Hidden Assumption":"That performance and trust will scale together unless explicitly managed.","Likely Failure Point":"Unclear thresholds for human override, weak evidence retention, or adversarial manipulation.","What They Didn''t Say":"Which controls matter most when mission continuity and operational decision quality—not just compliance—are the central goals.","Signature Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"questions":{"Source ID":"M29","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Which part of the human-machine relationship here is least mature?","CQ-3":"What evidence should a human see before trusting the model or autonomous action?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M29","Audio ID":"AA-M29","Episode / Briefing Title":"NIST SP 800-161r1 Cybersecurity Supply Chain Risk Management","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"A fast answer from a machine is not the same thing as a trusted answer. This source helps us understand the difference.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"visual":{"Source ID":"M29","Visual ID":"AV-M29","Asset Title":"Provenance and Product Assurance Chain","Recommended Format":"Lifecycle visual","Key Story the Visual Should Tell":"Requirements → code → build → deploy → update → evidence","Must-Show Elements":"Show where provenance breaks or survives.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M29","Linked Inject IDs":"INJ-05, INJ-08","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M29","Research Vector":"Investigate how cybersecurity controls translate into measurable mission assurance outcomes in hybrid space systems.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Space Cybersecurity; Mission Assurance"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M30','CISA Space Systems Critical Infrastructure Working Group resources','CISA','Tier 2 - Selective / elective source','Critical infrastructure','Space mission cybersecurity and hybrid architecture assurance','Mission Systems','Selective','https://www.esd.whs.mil/DD/',false,'{"brief":{"Source ID":"M30","Brief ID":"AB-M30","Proposed Brief Title":"CISA Space Systems Critical Infrastructure Working Group resources","Brief Abstract / Teaching Angle":"This Astrum Brief contextualizes the source for mission-critical space education. It identifies why the material matters now, what it teaches about mission systems, and how it can be translated into an exercise, scenario, or research question rather than remaining a passive reading.","Key Learning Payoff":"Space sector cyber resilience context.","What Changed / Why Now":"These frameworks are increasingly used as translational bridges between technical security practice and mission assurance requirements.","Suggested Dash Deliverable":"Short written analysis with one visual and a reflective diary entry."},"lens":{"Source ID":"M30","Lens ID":"RL-M30","Raven''s Lens Commentary":"The Raven''s Lens uses the source to surface the trust assumptions hiding underneath the official language.","Hidden Assumption":"That the architecture will behave as designed even when the mission is stressed, degraded, or contested.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"questions":{"Source ID":"M30","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M30","Audio ID":"AA-M30","Episode / Briefing Title":"CISA Space Systems Critical Infrastructure Working Group resources","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Astrum uses this source to turn static reading into a mission briefing about trust, resilience, and decision quality.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"visual":{"Source ID":"M30","Visual ID":"AV-M30","Asset Title":"Astrum Source Explainer","Recommended Format":"1-page visual brief","Key Story the Visual Should Tell":"Source purpose, system map, trust point, and one decision problem","Must-Show Elements":"A flexible format for any source.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M30","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Short written analysis with one visual and a reflective diary entry.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M30","Research Vector":"Identify a measurable trust, resilience, or mission-assurance gap implied by the source and frame it as a publishable research question.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Mission Systems"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
