insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M32','DoD Responsible Artificial Intelligence Strategy & Implementation Pathway','Department of War','Tier 1 - Core Astrum Source','AI governance','AI assurance, autonomy, and human judgment','Trusted AI & Autonomy','Core','https://standards.nasa.gov/',false,'{"brief":{"Source ID":"M32","Brief ID":"AB-M32","Proposed Brief Title":"DoD Responsible Artificial Intelligence Strategy & Implementation Pathway","Brief Abstract / Teaching Angle":"This brief frames the source around a single Astrum question: what evidence should a human decision-maker require before trusting model output or autonomous behavior? Students should finish with a grounded understanding of AI lifecycle risk, guardrails, adversarial pressure, audit needs, and where human judgment remains indispensable in mission-critical systems.","Key Learning Payoff":"Responsible AI implementation principles and pathways.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M32","Lens ID":"RL-M32","Raven''s Lens Commentary":"Astrum uses this source to separate performance from trust. A system can be accurate, fast, and still operationally untrustworthy if it cannot explain itself, resist manipulation, or preserve evidence of how a recommendation emerged.","Hidden Assumption":"That performance and trust will scale together unless explicitly managed.","Likely Failure Point":"Unclear thresholds for human override, weak evidence retention, or adversarial manipulation.","What They Didn''t Say":"What a commander should literally see before accepting a recommendation from a model or autonomous subsystem.","Signature Raven Question":"What evidence would make 