insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M40','CCSDS 351.0-M-1 Security Architecture for Space Data Systems','CCSDS','Tier 1 - Core Astrum Source','Space security architecture','Space data security architecture and cryptographic trust','Engineering & Technical Standards','Core','https://www.spaceforce.mil/USSF-Doctrine/',false,'{"brief":{"Source ID":"M40","Brief ID":"AB-M40","Proposed Brief Title":"Designing Trust Into Space Data Systems","Brief Abstract / Teaching Angle":"This brief translates technical standards language into the practical problem of protecting data authenticity, confidentiality, and integrity across space systems. The value-added layer is Astrum''s focus on provenance, auditability, key management, and the survivability of trusted records across organizational and technical boundaries.","Key Learning Payoff":"Reference security architecture for space data systems.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk."},"lens":{"Source ID":"M40","Lens ID":"RL-M40","Raven''s Lens Commentary":"Astrum treats these standards as the technical grammar of trust. They matter because they show where authenticity, confidentiality, and key stewardship must be embedded if data are to remain useful under operational pressure.","Hidden Assumption":"That technical correctness in cryptography automatically solves operational trust and governance.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"How Astrum''s trust-and-assurance method should be applied to this exact mission problem.","Signature Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"questions":{"Source ID":"M40","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"What trust boundary or dependency deserves the most attention?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M40","Audio ID":"AA-M40","Episode / Briefing Title":"Designing Trust Into Space Data Systems","Est. Duration":"7-9 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Astrum uses this source to turn static reading into a mission briefing about trust, resilience, and decision quality.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What mission decision becomes dangerous if the assumptions in this source prove false?"},"visual":{"Source ID":"M40","Visual ID":"AV-M40","Asset Title":"Space Data Security Stack","Recommended Format":"Stack diagram","Key Story the Visual Should Tell":"Keys, algorithms, links, data objects, operators, archives","Must-Show Elements":"Focus on authenticity and survivable trust.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M40","Linked Inject IDs":"INJ-02, INJ-12","Suggested Assignment IDs":"A14, A27","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"Annotated diagram + 1-2 page assurance memo or control crosswalk.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M40","Research Vector":"Assess how cryptographic and security-architecture standards can support end-to-end mission data verification at scale.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Engineering & Technical Standards"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
