insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M44','GAO Weapon Systems Cybersecurity reports','GAO','Tier 1 - Core Astrum Source','Oversight','Oversight, acquisition, transition, and strategic ecosystem','Space Cybersecurity; Mission Assurance; Acquisition & Strategy','Selective','https://www.spaceforce.mil/USSF-Doctrine/',false,'{"brief":{"Source ID":"M44","Brief ID":"AB-M44","Proposed Brief Title":"GAO Weapon Systems Cybersecurity reports","Brief Abstract / Teaching Angle":"This brief treats the source as a strategic signal. Rather than merely summarizing a posture statement, assessment, or portfolio page, the brief identifies what it reveals about priorities, bottlenecks, investment logic, transition challenges, and the type of capabilities the U.S. national security space ecosystem is actually rewarding right now.","Key Learning Payoff":"Audit findings on cyber risk in weapon-system acquisition.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M44","Lens ID":"RL-M44","Raven''s Lens Commentary":"Under the Raven''s Lens, these sources reveal the practical side of power: what gets funded, what gets delayed, what remains difficult to transition, and where rhetoric about capability still outruns institutional execution.","Hidden Assumption":"That security controls alone guarantee mission confidence without a clear evidentiary model.","Likely Failure Point":"A mismatch between stated policy intent and the technical evidence available during real mission stress.","What They Didn''t Say":"Which controls matter most when mission continuity and operational decision quality—not just compliance—are the central goals.","Signature Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"questions":{"Source ID":"M44","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Where are the highest-value trust boundaries: identity, software, ground segment, or data path?","CQ-3":"What evidence would you want before acting on information from this system?","CQ-4":"Which failure would hurt the mission most even if the organization remained technically compliant?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M44","Audio ID":"AA-M44","Episode / Briefing Title":"GAO Weapon Systems Cybersecurity reports","Est. Duration":"5-7 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Cybersecurity becomes mission-critical when a single weak link can quietly distort the operational picture.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"Where must trust be established at the source, and where can it be inherited?"},"visual":{"Source ID":"M44","Visual ID":"AV-M44","Asset Title":"From Funding Signal to Fielded Capability","Recommended Format":"Pipeline diagram","Key Story the Visual Should Tell":"Priority signal → prototyping → acquisition path → deployment → sustainment","Must-Show Elements":"Good for leadership and acquisition discussions.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M44","Linked Inject IDs":"INJ-12","Suggested Assignment IDs":"A05, A06, A07, A08","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M44","Research Vector":"Study how acquisition pathways, oversight structures, and innovation programs affect the transition of trusted-space technologies into operational use.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Space Cybersecurity; Mission Assurance; Acquisition & Strategy"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
