insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M50','STARCOM public training and doctrine resources','STARCOM','Tier 2 - Selective / elective source','Training / doctrine','Doctrine, warfighting, and institutional identity','ASTRUM Foundations; Spacepower & Guardian Doctrine; Workforce & Education','Core','https://spacewerx.us/',false,'{"brief":{"Source ID":"M50","Brief ID":"AB-M50","Proposed Brief Title":"STARCOM public training and doctrine resources","Brief Abstract / Teaching Angle":"This Astrum Brief converts the source into an operational reading of how the U.S. Space Force thinks about purpose, competitive advantage, campaigning, and warfighting. Students use it not just to memorize doctrine, but to identify how institutional ideas shape force design, mission command, risk tolerance, and the meaning of space superiority. The brief should finish with a short section on what the document implies for cyber trust, data assurance, and multidisciplinary Guardian education.","Key Learning Payoff":"Guardian development, doctrine and readiness resources.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash."},"lens":{"Source ID":"M50","Lens ID":"RL-M50","Raven''s Lens Commentary":"Astrum reads this source as a statement of worldview. The document tells us what the Service believes about advantage, competition, and mission success. The proprietary layer is asking what this worldview assumes about trustworthy information, survivable records, cyber resilience, and the ability of a commander to distinguish confidence from mere data volume.","Hidden Assumption":"That commanders will have timely, coherent, and sufficiently trusted information when doctrine must be applied.","Likely Failure Point":"Unclear thresholds for human override, weak evidence retention, or adversarial manipulation.","What They Didn''t Say":"How authoritative truth is preserved when the mission depends on mixed military, allied, and commercial data.","Signature Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"questions":{"Source ID":"M50","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Which part of the human-machine relationship here is least mature?","CQ-3":"What evidence should a human see before trusting the model or autonomous action?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M50","Audio ID":"AA-M50","Episode / Briefing Title":"STARCOM public training and doctrine resources","Est. Duration":"8-10 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"Spacepower sounds abstract until a commander must act without certainty. This source tells us what the Service expects to matter when that moment comes.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"visual":{"Source ID":"M50","Visual ID":"AV-M50","Asset Title":"Doctrine-to-Mission Map","Recommended Format":"1-page doctrine map","Key Story the Visual Should Tell":"Purpose → mission functions → decision burdens → trust dependencies","Must-Show Elements":"Use icon layers for doctrine, missions, cyber, intelligence, and command.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M50","Linked Inject IDs":"INJ-05, INJ-10","Suggested Assignment IDs":"A01, A03, A39, A40","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"2-page memo or 6-slide commander brief uploaded in Dash.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M50","Research Vector":"Research how doctrine and strategic guidance account for trusted data, cyber resilience, and commercial integration in actual decision chains.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"ASTRUM Foundations; Spacepower & Guardian Doctrine; Workforce & Education"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
