insert into public.sources (id,title,official_source,tier,domain,theme,pathways,core_selective,public_url,phase2,content) values ('M57','Air Force Research Laboratory Space Vehicles Directorate public resources','AFRL','Tier 2 - Selective / elective source','R&D','AI assurance, autonomy, and human judgment','Mission Systems','Selective','https://www.gps.gov/',false,'{"brief":{"Source ID":"M57","Brief ID":"AB-M57","Proposed Brief Title":"Air Force Research Laboratory Space Vehicles Directorate public resources","Brief Abstract / Teaching Angle":"This brief frames the source around a single Astrum question: what evidence should a human decision-maker require before trusting model output or autonomous behavior? Students should finish with a grounded understanding of AI lifecycle risk, guardrails, adversarial pressure, audit needs, and where human judgment remains indispensable in mission-critical systems.","Key Learning Payoff":"Technology research context for space systems.","What Changed / Why Now":"Astrum uses this source not as static reading, but as a current signal about how mission-critical space systems are being designed, governed, or stressed.","Suggested Dash Deliverable":"AI assurance worksheet + decision memo or audit evidence package."},"lens":{"Source ID":"M57","Lens ID":"RL-M57","Raven''s Lens Commentary":"Astrum uses this source to separate performance from trust. A system can be accurate, fast, and still operationally untrustworthy if it cannot explain itself, resist manipulation, or preserve evidence of how a recommendation emerged.","Hidden Assumption":"That performance and trust will scale together unless explicitly managed.","Likely Failure Point":"Unclear thresholds for human override, weak evidence retention, or adversarial manipulation.","What They Didn''t Say":"What a commander should literally see before accepting a recommendation from a model or autonomous subsystem.","Signature Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"questions":{"Source ID":"M57","CQ-1":"What mission problem is this source really trying to solve?","CQ-2":"Which part of the human-machine relationship here is least mature?","CQ-3":"What evidence should a human see before trusting the model or autonomous action?","CQ-4":"Where could adversary pressure, ambiguity, or simple failure distort the picture?","CQ-5":"How would you convert this reading into a commander brief, exercise, or research question?"},"audio":{"Source ID":"M57","Audio ID":"AA-M57","Episode / Briefing Title":"Air Force Research Laboratory Space Vehicles Directorate public resources","Est. Duration":"6-8 min","Voice / Tone":"Documentary-intelligence / authoritative / calm","Opening Hook":"A fast answer from a machine is not the same thing as a trusted answer. This source helps us understand the difference.","Segment 1":"Situation: define the mission context, the document type, and why it exists now.","Segment 2":"Core content: explain the architecture, framework, strategy, or doctrine in plain operational language.","Segment 3":"Astrum translation: identify the cyber, trust, AI, resilience, or command implications and end with a Raven question.","Closing Raven Question":"What evidence would make you trust—or reject—this machine-generated recommendation?"},"visual":{"Source ID":"M57","Visual ID":"AV-M57","Asset Title":"Human–Machine Trust Boundary","Recommended Format":"Decision-flow diagram","Key Story the Visual Should Tell":"Inputs, model, guardrails, confidence, override, audit evidence","Must-Show Elements":"Show where human judgment enters and what evidence is visible.","Production Notes":"Use Astrum visual language: dark, precise, premium, and mission-focused."},"aegis":{"Source ID":"M57","Linked Inject IDs":"INJ-05","Suggested Assignment IDs":"A39","Suggested Weekly Activity":"Read the source through the Astrum Brief and Raven''s Lens, listen to or review the audio script, study the visual asset concept, then complete the linked mission task or AEGIS scenario response.","Mission Task Prompt":"Translate the source into a concrete mission decision, architecture judgment, or research gap statement.","Dash Deliverable":"AI assurance worksheet + decision memo or audit evidence package.","Evaluation Focus":"Systems thinking, mission relevance, trust-and-assurance reasoning, decision communication, and evidence quality."},"research":{"Source ID":"M57","Research Vector":"Examine explainability, auditability, and adversarial robustness requirements for AI or autonomous components in mission-critical space contexts.","Master''s-Level Option":"20-30 page applied research paper or design study linked to a weekly work plan and AEGIS scenario.","PhD / Publication Option":"Publication-oriented manuscript on the unresolved trust, assurance, architecture, or workforce issue surfaced by the source.","Cross-Links / Best-Fit Pathways":"Mission Systems"}}'::jsonb) on conflict (id) do update set title=excluded.title, official_source=excluded.official_source, tier=excluded.tier, domain=excluded.domain, theme=excluded.theme, pathways=excluded.pathways, core_selective=excluded.core_selective, public_url=excluded.public_url, phase2=excluded.phase2, content=excluded.content, updated_at=now();
